      SUBROUTINE OUTFITCC     MAKES A RUN THROUGH THE BEAM TRANSPORT SYSTEM AND PRINTSC     OUTPUTCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'BROAD.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA0B.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA1C.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'DSPECR.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM0C.CIN'      INCLUDE 'ELM0D.CIN'      INCLUDE 'ELM1D.CIN'      INCLUDE 'ELM4A.CIN'      INCLUDE 'ELM8G.CIN'      INCLUDE 'ELM9.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM13B.CIN'      INCLUDE 'ELM13C.CIN'      INCLUDE 'ELM15B.CIN'      INCLUDE 'ELM15C.CIN'      INCLUDE 'ELM31A.CIN'      INCLUDE 'FLUSHC.CIN'      INCLUDE 'IMAGE.CIN'      INCLUDE 'IOUNIT.CIN'      INCLUDE 'LBLSVE.CIN'      INCLUDE 'LXRAN.CIN'      INCLUDE 'PRINTL.CIN'      INCLUDE 'STEPT1.CIN'CC     LOCAL VARIABLESC      INTEGER      IDATA, NSLIT      REAL         DATAR, WORK1      EXTERNAL     DATAR, IDATACC-------------------------------------------------------------------C      IF (.NOT. LSTEP .OR. BROAD) WRITE (NOUT,8999) IMAGE 8999 FORMAT (1H1,A80/)      CALL PARSET      CALL INITZE      DO 5 J = 1, 33    5 DSPEC_VAL(J) = 0.0C      IF (NEL .LE. 0) GO TO 5300   10 I = ISTOR(NUM)      TYPE = IDATA(I)      IF (TYPE .GE. 82 .AND. TYPE .LE. 86) GO TO 70      IF (TYPE .LE. 0 .OR. TYPE .GE. 50) GO TO 5200      CALL SKETCH(NUM)      CALL DEPICT      IF (.NOT. ATWE) GO TO 5200C      IF (PRON .AND. ELPR .AND. .NOT. LCPR .AND. TYPE .NE. 13) THEN        WORK1 = LC/UFLOOR(1)        WRITE (NOUT,9001) WORK1, XFLOOR(1)        LCPR = .TRUE.      ENDIF 9001 FORMAT (1H ,8X,F10.3,1X,A4)C      IF (TYPE .EQ. 31) LABELSVE = LABEL(NUM)CC     POSSIBLE INITIAL MISALIGNMENTSC      CALL POSSIM      IF (FLUSHL) GO TO 5500CC     SIMPLE ELEMENTSC      IF (RABL .AND. WFRN) GO TO 200      IF (RABL) GO TO 100   70 TYPEC = TYPE      LXRAN = TYPE .LT. 50      CALL ELICIT      IF (FLUSHL) GO TO 5500      IF (TYPE .LE. 0) GO TO 5200      IF (TYPE .EQ. 15) GO TO 5200      IF (.NOT. LSTEPN) CALL POSTER      IF (TYPE .NE. 30 .AND. (TYPE .NE. 14 .OR. NEXT .NE. 14)) THEN        IF (.NOT. LSTEPN) THEN           CALL VPRINT          CALL MPRINT        ENDIF      ENDIFCC     UPDATE USED TO MARK BEGINNING OF MISALIGNMENTC      IF (TYPE .EQ. 6 .OR. TYPE .EQ. 37) THEN        NSLIT = IFIX(DATA(I+1))        IF (NSLIT .EQ. 0) THEN          CALL UPMARK          IF (FLUSHL) GO TO 5500        ENDIF      ENDIF      GO TO 5200CC     SIMPLE ELEMENTS WITH POSSIBLE TILTC  100 IF (TYPE .EQ. 2 .OR. TYPE .EQ. 4) GO TO 150      CALL ELTILT      IF (FLUSHL) GO TO 5500      GO TO 5000CC     BENDING MAGNETS WITH FRINGE FIELD SPECIFIED BY SEPARATE ELEMENTC  150 CALL EL242      IF (FLUSHL) GO TO 5500      GO TO 5000CC     COMPOUND ELEMENTSC  200 CALL ELCOMP      IF (FLUSHL) GO TO 5500      L = LBENDCC     LOOP THROUGH MISALIGNMENTS BY NAMEC 5000 IF (.NOT. ALGR .AND. NMISRB .NE. 0) CALL AGENDR(1)CC     ADVANCE TO NEXT ELEMENTC 5200 IF (MKG .AND. NUM .EQ. NMARKE) CALL AGENDA(2)      IF (ALGR .AND. NUM .EQ. NMISRE) CALL AGENDR(2)      IF (MADL .OR. TRANSPORTL .OR. LATDEFL .OR. STRUCTL .OR.      1    ACADL .OR. FILEL) CALL LATSTOR      NUM = NUM + NDIF      IF (.NOT. MKG .AND. NUSE .NE. 0 .AND. NUM .GT. NUSE) GO TO 5300      IF (NUM .LE. NEL) GO TO 10CC     END OF BEAM LINE - PRINT LENGTHC 5300 CONTINUE      IF (.NOT. LSTEP .OR. BROAD) THEN        WORK1 = LC/UFLOOR(1)        WRITE (NOUT,9021) WORK1, XFLOOR(1)      ENDIF 9021 FORMAT (1H0,8X,'*LENGTH*',F17.5,1X,A4) 5500 RETURN      END